  position: relative;
}
.visual.phone { width: 126px; height: 184px; border-radius: 28px; background: linear-gradient(135deg,#20222a,#7e91ad); }
.visual.phone::after { content:""; position:absolute; inset: 13px; border-radius: 19px; border: 1px solid rgba(255,255,255,.18); }
.visual.laptop { width: 230px; height: 146px; border-radius: 18px; background: linear-gradient(155deg,#d7e7ff,#f9fbff); border-bottom: 16px solid #c8cdd4; }
.visual.tablet { width: 184px; height: 142px; border-radius: 23px; background: linear-gradient(135deg,#0f172a,#75a6ff); }
.visual.audio { width: 132px; height: 132px; border-radius: 50%; background: radial-gradient(circle,#fff 0 28%,#f2f2f4 29% 55%,#151519 56%); }
.visual.watch { width: 118px; height: 150px; border-radius: 38px; background: linear-gradient(135deg,#111,#4d5665); }
.visual.accessory { width: 150px; height: 150px; border-radius: 34px; background: linear-gradient(135deg,#ff815c,#ffd3bc); }
.visual.desktop { width: 210px; height: 150px; border-radius: 20px; background: linear-gradient(135deg,#ebeef4,#fff); border-bottom: 20px solid #cdd2db; }
.carousel-btn {
