  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  padding: 14px;
  background: #fff;
}
.hero-tile {
  min-height: 590px;
  border-radius: 0;
  background: #f5f5f7;
  padding: 54px 28px 28px;
  text-align: center;
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
}
.hero-tile.featured { grid-column: span 2; min-height: 660px; background: linear-gradient(180deg,#f8fbff,#edf4ff); }
.hero-tile.dark { background: #050508; color: #fff; }
.hero-tile.warm { background: linear-gradient(180deg,#fff7ef,#f5f5f7); }
.hero-tile h2 { font-size: clamp(38px, 5vw, 62px); line-height: .98; letter-spacing: -.055em; margin-bottom: 8px; }
.hero-tile p { color: inherit; opacity: .82; font-size: 22px; margin-bottom: 18px; }
.ctas { display:flex; gap: 12px; justify-content:center; flex-wrap: wrap; position:relative; z-index:2; }
.btn { border: 1px solid var(--blue); color: var(--blue); border-radius: 999px; padding: 10px 18px; font-size: 15px; background: transparent; cursor: pointer; }
.btn.primary { background: var(--blue); color: #fff; }
.hero-art {
  margin-top: auto;
  width: min(70%, 520px);
  height: 280px;
  border-radius: 46px;
  background: linear-gradient(135deg,#dbe8ff,#ffffff 42%,#e5fff3);
  box-shadow: inset 0 -35px 80px rgba(0,0,0,.08), 0 30px 90px rgba(0,0,0,.12);
}
.hero-tile.dark .hero-art { background: linear-gradient(135deg,#151824,#485a7a,#f0f6ff); }
.hero-tile.trade .hero-art { background: radial-gradient(circle at 30% 35%,#bcf0c7 0 20%, transparent 21%), linear-gradient(135deg,#e6f8e9,#fff); }
.info-grid { display:grid; grid-template-columns: repeat(3,1fr); gap: 18px; max-width: var(--max); margin:0 auto; padding: 8px 24px 26px; }
.info-card { background:#fff; border-radius: 26px; padding: 28px; min-height: 220px; box-shadow: var(--shadow); }
.info-card .icon { font-size: 32px; margin-bottom: 18px; }
.info-card h3 { font-size: 23px; letter-spacing: -.03em; margin-bottom: 8px; }
.promo-card { background: linear-gradient(135deg,#101115,#35405a); color:#fff; }
.promo-card p { color: rgba(255,255,255,.75); }
.tabs { display:flex; justify-content:center; gap: 10px; flex-wrap:wrap; margin: 0 0 24px; }
.tab { border:0; padding: 11px 18px; border-radius: 999px; background:#e8e8ed; color:#333; cursor:pointer; }
.tab.active { background: var(--ink); color:#fff; }
.tab-panel { display:none; }
.tab-panel.active { display:block; }
.ent-card { flex-basis: 310px; min-height: 330px; color:#fff; background: linear-gradient(135deg,#15171c,#476080); display:flex; flex-direction:column; justify-content:flex-end; }
.ent-card h3 { font-size: 30px; }
.ent-card p { color: rgba(255,255,255,.78); }
.category-hero {
  background:#fff;
  text-align:center;
  padding: 70px 24px 36px;
}
.category-hero h1 { font-size: clamp(48px, 8vw, 86px); }
.category-hero p { color:var(--muted); font-size: 23px; max-width:720px; margin: 0 auto 26px; }
.section-nav {
  position: sticky;
  top: 48px;
  z-index: 15;
  background: rgba(255,255,255,.86);
  backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--line);
  overflow-x: auto;
}
.section-nav .inner { max-width: var(--max); margin:0 auto; display:flex; gap: 24px; padding: 14px 24px; white-space:nowrap; font-size:14px; }
.section-nav a { color:#444; }
.section-nav a:hover { color:var(--blue); }
.quick-links { display:flex; flex-wrap:wrap; gap: 12px; max-width: var(--max); padding: 0 24px 42px; margin: 0 auto; }
.quick-links a { background:#e8e8ed; border-radius: 999px; padding: 12px 18px; font-weight: 600; }
.footer { background:#f5f5f7; border-top: 1px solid var(--line); color:#515154; font-size: 13px; }
.footer-inner { max-width: 1060px; margin:0 auto; padding: 26px 18px; }
.footnote { border-bottom:1px solid var(--line); padding-bottom: 18px; line-height:1.45; color:#6e6e73; }
.footer-grid { display:grid; grid-template-columns: repeat(4,1fr); gap: 24px; padding: 20px 0; }
.footer-section h4 { color:var(--ink); font-size: 13px; margin: 0 0 10px; }
.footer-section button { all: unset; color:var(--ink); font-weight:700; display:block; width:100%; }
.footer-section ul { list-style:none; padding:0; margin:0; display:grid; gap: 8px; }
.legal { border-top:1px solid var(--line); padding-top: 14px; color:#6e6e73; }
@media (max-width: 900px) {
  .nav-links { gap: 14px; overflow-x: auto; }
  .hero-store { grid-template-columns:1fr; padding-top: 42px; }
  .grid-showcase { grid-template-columns: 1fr; }
  .hero-tile.featured { grid-column: span 1; }
  .hero-tile { min-height: 520px; }
  .info-grid { grid-template-columns: 1fr 1fr; }
  .card { flex-basis: 300px; }
  .footer-grid { grid-template-columns: repeat(2,1fr); }
}
@media (max-width: 640px) {
  .nav { justify-content:flex-start; overflow-x:auto; }
  .nav-actions { margin-left:auto; }
  .hero-store .subtitle { font-size: 34px; }
  .section { padding: 28px 0; }
  .section-header { display:block; }
  .card { flex-basis: 84vw; min-height: 390px; }
  .carousel-btn { width:38px; height:38px; font-size:24px; }
  .hero-tile { min-height: 470px; padding-top: 38px; }
  .hero-tile p { font-size: 19px; }
  .hero-art { width: 88%; height: 210px; }
  .info-grid { grid-template-columns: 1fr; }
  .footer-grid { display:block; padding: 6px 0 14px; }
  .footer-section { border-bottom:1px solid var(--line); }
  .footer-section button { padding: 13px 0; position:relative; cursor:pointer; }
  .footer-section button::after { content:'+'; position:absolute; right: 2px; }
  .footer-section.open button::after { content:'–'; }
  .footer-section ul { display:none; padding: 0 0 14px; }
  .footer-section.open ul { display:grid; }
}
EOF

cat > /app/output/script.js <<'EOF'
document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('[data-carousel]').forEach((carousel) => {
    const track = carousel.querySelector('.track');
    const prev = carousel.querySelector('.prev');
    const next = carousel.querySelector('.next');
    if (!track) return;
    const scrollByAmount = () => Math.max(280, Math.floor(track.clientWidth * 0.82));
    prev?.addEventListener('click', () => track.scrollBy({ left: -scrollByAmount(), behavior: 'smooth' }));
    next?.addEventListener('click', () => track.scrollBy({ left: scrollByAmount(), behavior: 'smooth' }));
  });

  document.querySelectorAll('[data-tabs]').forEach((tabs) => {
    const buttons = tabs.querySelectorAll('[data-tab]');
    const panels = tabs.parentElement.querySelectorAll('[data-panel]');
    buttons.forEach((button) => {
      button.addEventListener('click', () => {
        const target = button.dataset.tab;
        buttons.forEach((b) => b.classList.toggle('active', b === button));
        panels.forEach((panel) => panel.classList.toggle('active', panel.dataset.panel === target));
      });
    });
  });

  document.querySelectorAll('.footer-section button').forEach((button) => {
    button.addEventListener('click', () => {
      if (window.matchMedia('(max-width: 640px)').matches) {
        button.closest('.footer-section').classList.toggle('open');
      }
    });
  });
});
EOF

